export function bodyDimsFor(src) {
  if (!src) return undefined;
  const f = src.split("/").pop();
  const d = BODY_DIMS[f];
  return d ? { width: d[0], height: d[1] } : undefined;
}

export function heroDimsFor(src) {
  if (!src) return undefined;
  const f = src.split("/").pop();
  const d = HERO_DIMS[f];
  return d ? { width: d[0], height: d[1] } : undefined;
}

// Heroes render full viewport width; bodies render ~592px in the
// 2-col grid @1280 and full width (vw-40px) below the 640px breakpoint.
//
// DESIGN CYCLE 3, P2-1 (2026-11-16): height-aware hero sizes. The mobile
// hero slot is TALL (content-driven, ~650-850px at 390px) while the 800w
// variant is SHORT (800x450, 800x325 emergency), so width-based sizes
// picked 800w and cover upscaled it 1.06-2.21x on 39/40 pages. Claiming
// a 1600px display width at narrow viewports makes the browser pick the
// original instead, which is tall enough to cover the slot (worst
// remaining: emergency 1600x650 into a ~650px slot = ~1.00x).
// Short-original heroes (height <= 700: emergency only) keep the claim
// up to 1280px, because their 1200w rung (1200x488) is still shorter than
// the ~520-600px desktop hero slot; every other hero's 1200w rung
// (1200x675 / 1200x800) covers its desktop slot, so the claim ends at
// 820px for them. Above 1280px the browser picks the largest candidate
// (the original) anyway. The preload link Next emits follows the same
// sizes, so mobile fetches the original once — no double download.
// SPEED FIX 2026-11-17 (F1b): F1-as-specified ("(max-width: 820px) 1200px")
// was a PROVEN NO-OP — Lighthouse mobile is DPR 1.75, so a 1200px claim
// needs a 2100w candidate and the browser still picks the 1600w original
// (F1 runs: hero still hero-*.webp 119/120/190 KB). To actually pick the
// 1200w rung on phones the claim must satisfy claim x DPR <= 1200, i.e.
// <= 685px at DPR 1.75 (<= 600px at DPR 2). Phones (<=480 CSS px) claim
// 600px: DPR 1.75 -> 1050w -> 1200w rung; DPR 2 -> 1200w; DPR 3 -> 1800w
// -> original (safe). 481-820px keeps the 1600px claim (Cycle 3 quality
// decision untouched for tablets); desktop unchanged (100vw).
export const HERO_SIZES = "(max-width: 480px) 600px, (max-width: 820px) 1600px, 100vw";
export const HERO_SIZES_SHORT = "(max-width: 1280px) 1600px, 100vw";

export function heroSizesFor(src) {
  const d = heroDimsFor(src);
  if (d && d.height <= 700) return HERO_SIZES_SHORT;
  return HERO_SIZES;
}
export const BODY_SIZES = "(max-width: 640px) 100vw, 600px";

// SPEED FIX 2026-11-17 (F5): home card images. Cards render 362px wide
// @390 (mobile, DPR 1.75 -> 634px needed) and 387px @1350 (desktop,
// DPR 1). The 600w rung covers both slots (1.55x desktop, 0.95x mobile);
// the 800w original stays for high-DPR desktops (claim x DPR >= 800).
// Sizes claim 340px at <=640px so mobile picks the 600w rung (340 x 1.75
// = 595 <= 600); above 640px the 400px claim picks 600w at DPR 1-1.5
// and the original at DPR 2+.
export const CARD_SIZES = "(max-width: 640px) 340px, 400px";

export function cardSrcsetFor(src) {
  if (!src) return undefined;
  if (!src.startsWith("/images/card-")) return undefined;
  return src.replace(/\.webp$/, "-600w.webp") + " 600w, " + src + " 800w";
}
